import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <class TA, class TB, class TC>
__global__ static void
triu_gemm_device(int M, int N, int K,
                  TA const* A, int ldA,
                  TB const* B, int ldB,
                  TC*       C, int ldC)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 8;

  int m0 = blockIdx.x * BM;
  int n0 = blockIdx.y * BN;

  // Entire tile is strictly below the diagonal -> output stays zero.
  if (m0 > n0 + BN - 1) return;

  // Represent full tensors (row-major)
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(ldA, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(K, N), make_stride(ldB, Int<1>{}));
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(ldC, Int<1>{}));

  auto cta_tiler = make_shape(Int<BM>{}, Int<BN>{}, Int<BK>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{}); // (BM,BK,KTILES)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{}); // (BK,BN,KTILES)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{}); // (BM,BN)

  // Shared memory
  __shared__ TA smemA[BM*BK];
  __shared__ TB smemB[BK*BN];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<BM>{}, Int<BK>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<BK>{}, Int<BN>{}));

  // Thread layouts (256 threads total)
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X,_1>{});

  Tensor tCrC = make_tensor<TC>(make_shape(Int<8>{}, Int<8>{}));
  clear(tCrC);

  // Restrict K-tile loop using triangular structure:
  // A[m,k] != 0 only if k >= m  => need k >= m0
  // B[k,n] != 0 only if n >= k  => need k <= n0 + BN - 1
  int K_TILE_MAX = size<2>(tAgA);
  int k_start = m0 / BK;
  int k_end   = (n0 + BN + BK - 1) / BK;
  if (k_start < 0) k_start = 0;
  if (k_end > K_TILE_MAX) k_end = K_TILE_MAX;

  for (int k_tile = k_start; k_tile < k_end; ++k_tile) {
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);

    __syncthreads();

    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  // Epilogue: write result with upper-triangular masking.
  int tid  = threadIdx.x;
  int trow = tid % 16;
  int tcol = tid / 16;

  #pragma unroll
  for (int i = 0; i < 8; ++i) {
    int gm = m0 + trow + i * 16;
    if (gm >= M) continue;
    #pragma unroll
    for (int j = 0; j < 8; ++j) {
      int gn = n0 + tcol + j * 16;
      if (gn >= N) continue;
      TC val = (gm <= gn) ? tCrC(i, j) : TC(0);
      mC(gm, gn) = val;
    }
  }
}

torch::Tensor triu_matmul_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
  TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
  TORCH_CHECK(A.size(0) == B.size(0), "A and B must have the same size");

  int N = (int)A.size(0);

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  // Output initialized to zero, so skipped (below-diagonal) tiles are correct
  // without any extra work.
  auto C = torch::zeros({N, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  int ldA = N, ldB = N, ldC = N;

  dim3 dimBlock(256);
  dim3 dimGrid((N + 127) / 128, (N + 127) / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triu_gemm_device<float, float, float><<<dimGrid, dimBlock, 0, stream>>>(
      N, N, N, ptrA, ldA, ptrB, ldB, ptrC, ldC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_gemm_device launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

triu_matmul_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triu_matmul_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs matrix multiplication C = A * B for upper triangular matrices,
    implemented with a single fused CuTe GEMM kernel that skips fully
    below-diagonal tiles, restricts the K-loop using the triangular
    structure, and applies the upper-triangular masking in the epilogue.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = triu_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.triu_matmul_forward(A, B)

